REMAINING_HEADER = "X-Practice-Remaining"
ME_PATH = "/me"
# A 429 with a short Retry-After is the per-second rate limit: wait and retry. Any other 429 (the
# practice quota, too many open sessions) does not go away by retrying.
MAX_RETRY_AFTER_S = 5


class ArenaError(Exception):
    def __init__(self, status: int, detail):
        super().__init__(f"HTTP {status}: {detail}")
        self.status, self.detail = status, detail


class ArenaClient:
    def __init__(
        self,
        base_url=None,
        api_key=None,
        *,
        retries=3,
        transport=None,
        timeout=TIMEOUT_S,
        rate=CALLS_PER_SECOND,
    ):
        base_url = (base_url or os.environ.get("ARENA_URL", "")).rstrip("/")
        if not base_url:
            raise ValueError("set ARENA_URL (e.g. https://…) or pass base_url")
        key = api_key or os.environ.get("ARENA_API_KEY")
        headers = {"X-API-Key": key} if key else {}
        self.retries, self.rate, self._lock, self._next = retries, rate, threading.Lock(), 0.0
        self.practice_remaining = None  # from the last practice reply that said so
        self.http = httpx.Client(base_url=f"{base_url}/v1", headers=headers, timeout=timeout, transport=transport)

    def _pace(self):
        with self._lock:
            now = time.monotonic()
            wait, self._next = self._next - now, max(now, self._next) + 1 / self.rate
        if wait > 0:
            time.sleep(wait)

    def _call(self, method, path, body=None, params=None, raw=False):
        headers = {MOVE_ID_HEADER: uuid.uuid4().hex} if method == "POST" else {}
        for attempt in range(self.retries + 1):
            self._pace()
            try:
                r = self.http.request(method, path, json=body, params=params, headers=headers)
            except httpx.TransportError:
                if attempt == self.retries:
                    raise
                wait = None
            else:
                wait = r.headers.get("Retry-After", "")
                short = wait.isdigit() and int(wait) <= MAX_RETRY_AFTER_S
                if r.status_code not in RETRY_STATUS or attempt == self.retries or (r.status_code == 429 and not short):
                    break
            time.sleep(float(wait) if wait and wait.isdigit() else 0.5 * 2**attempt)
        if (left := r.headers.get(REMAINING_HEADER, "")).isdigit():
            self.practice_remaining = int(left)
        if r.status_code >= 400:
            try:
                detail = r.json().get("detail", r.text)
            except (ValueError, AttributeError):
                detail = r.text
            raise ArenaError(r.status_code, detail)
        return r.content if raw else r.json()

    def register(self, team_name, event_code):
        """arena-sim only: the simulator hands out its own keys. On the arena, the organisers
        give each team its key."""
        return self._call("POST", "/register", {"team_name": team_name, "event_code": event_code})

    def me(self):
        """Your team: practice sessions used and left, when the quota resets, best score per case."""
        return self._call("GET", ME_PATH)

    def cases(self, set_="practice"):
        return self._call("GET", "/cases", params={"set": set_})

    def open_session(self, case_id):
        return self._call("POST", "/sessions", {"case_id": case_id})

"""Astra routing and failure behaviour without external calls or real credentials."""

import json
import time

import httpx
import pytest

from hollerau.analytical.router import ASTRA, Router

CASE = {
    "negotiable": ["unit_price", "contract_months", "index_clause"],
    "term_options": {
        "contract_months": [12, 24],
        "index_clause": [None],
    },
}
SOURCES = {"reply": "We require an index clause for a 24-month contract."}
REVIEW = {
    "issues": [{"source_id": "reply", "quote": SOURCES["reply"], "explanation": "Check the index."}],
    "conditions": [],
    "alternative_terms": [],
}


def response(obj=REVIEW, status="completed"):
    return {
        "status": status,
        "output": [
            {"type": "reasoning", "summary": []},
            {"type": "message", "content": [{"type": "output_text", "text": json.dumps(obj)}]},
        ],
        "usage": {"input_tokens": 100, "output_tokens": 40},
    }


def test_astra_and_qwen_use_separate_hosts_keys_and_output_protocols():
    requests = []

    def handler(req):
        body = json.loads(req.content)
        requests.append((req, body))
        if req.url.host == "router.huggingface.co":
            assert req.headers["Authorization"] == "Bearer hf-test"
            return httpx.Response(
                200,
                json={
                    "choices": [
                        {
                            "message": {
                                "content": json.dumps(
                                    {
                                        "interpretations": [],
                                        "signals": [],
                                        "ambiguities": [],
                                    }
                                )
                            }
                        }
                    ]
                },
            )
        assert req.url == "https://api.openai.com/v1/responses"
        assert req.headers["Authorization"] == "Bearer openai-test"
        assert body["model"] == ASTRA and body["store"] is False
        assert body["reasoning"] == {"effort": "medium"}
        assert body["max_output_tokens"] == 4096
        assert body["text"]["format"]["type"] == "json_schema"
        assert body["text"]["format"]["strict"] is True
        assert "json" in body["input"].lower()  # Required by the live Responses JSON-mode validator.
        assert not {"temperature", "max_tokens", "chat_template_kwargs", "tools"} & body.keys()
        assert 0 < req.extensions["timeout"]["read"] <= 25
        return httpx.Response(200, json=response())

    router = Router("hf-test", httpx.MockTransport(handler), reviewer="astra", review_key="openai-test")
    router.analyse({}, [], time.monotonic() + 30)
    for _ in range(2):
        review = router.review(SOURCES, CASE, {}, time.monotonic() + 30)
    assert len(requests) == 2  # cached review costs nothing on repetition
    assert review["reviewer"] == ASTRA and review["issues"]
    assert router.calls[-1]["usage"]["output_tokens"] == 40
    assert "openai-test" not in json.dumps(router.calls)
    router.close()


